window.__GLOSSARY__ = {"acceptable_use_policies":{"id":"acceptable_use_policies","title":"acceptable use policies","definition":"An acceptable use policy is a set of rules specifying the legal and ethical use of a system and the consequences of noncompliance.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"access_controls":{"id":"access_controls","title":"Access controls","definition":"Access controls are designed to protect systems from unauthorized access in order to preserve data integrity.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"accountability":{"id":"accountability","title":"accountability","definition":"Accountability refers to issues involving both a user’s and organization’s responsibilities and liabilities.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"adware":{"id":"adware","title":"Adware","definition":"Adware is a form of spyware that collects information about the user (without the user’s consent) to determine which advertisements to display in the user’s Web browser.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"aggregation":{"id":"aggregation","title":"Aggregation","definition":"How Power BI combines a field's values in a visual: sum by default, or average, count, minimum, or maximum.","context":null,"tier":"support","tags":["support","power-bi","band-red"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"allocation":{"id":"allocation","title":"allocation","definition":"The allocation approach to a distributed DBMS combines fragmentation and replication, with each site storing the data it uses most often.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"applied_steps":{"id":"applied_steps","title":"Applied Steps","definition":"The Query Editor's list of every shaping step, in order. Power BI replays the list each time the data refreshes.","context":null,"tier":"support","tags":["support","power-bi","band-blue"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"argument":{"id":"argument","title":"Argument","definition":"A value or expression placed inside a function's parentheses. A function requires an argument to pass it a value; SUM(Sales[SalesAmount]) has one.","context":null,"tier":"exam","tags":["power-bi","dax","band-green"],"refs":["Exam 2 Review deck, slides 44-45","Glossary: examples/exam2-knaflic-board"]},"artificial_intelligence_ai":{"id":"artificial_intelligence_ai","title":"Artificial intelligence (AI)","definition":"Artificial intelligence (AI) consists of related technologies that try to simulate and reproduce human thought and behavior, including thinking, speaking, feeling, and reasoning. AI technologies apply computers to areas that require knowledge, perception, reasoning, understanding, and cognitive abilities.","context":null,"tier":"exam","tags":["mod-09","band-red"],"refs":["Glossary: examples/mis-09-ai"]},"artificial_neural_networks_anns":{"id":"artificial_neural_networks_anns","title":"Artificial neural networks (ANNs)","definition":"Artificial neural networks (ANNs) are networks that learn and are capable of performing tasks that are difficult with conventional computers, such as playing chess, recognizing patterns in faces and objects, and filtering spam e-mail.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"asymmetric_encryption":{"id":"asymmetric_encryption","title":"Asymmetric encryption","definition":"Asymmetric encryption uses two keys: a public key known to everyone and a private or secret key known only to the recipient. A message encrypted with a public key can be decrypted only with the same algorithm used by the public key and requires the recipient’s private key, too. Any people who intercept the message cannot decrypt it because they do not have the private key.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"audience":{"id":"audience","title":"Audience","definition":"The people you are communicating to. Narrow it as far as you can; the review deck asks whether to present to the widest possible audience or a specific one, and the specific one is the answer.","context":null,"tier":"exam","tags":["knaflic-ch1","band-yellow"],"refs":["Exam 2 Review deck, slide 42","Glossary: examples/exam2-knaflic-board"]},"augmented_intelligence":{"id":"augmented_intelligence","title":"Augmented intelligence","definition":"The goal of augmented intelligence is to complement decision makers, not replace them.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"authentication_tokens":{"id":"authentication_tokens","title":"Authentication tokens","definition":"Authentication tokens improve security by transmitting a security token among connected applications. The user logs in once with approved credentials, and then a unique token is generated and shared with connected applications or Web sites to verify the user’s identity for a given period.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"availability":{"id":"availability","title":"Availability","definition":"Availability means that computers and networks are operating, and that authorized users can access the information they need. It also means a quick recovery in the event of a system failure or disaster.","context":null,"tier":"exam","tags":["mod-05","band-green"],"refs":["Glossary: examples/mis-05-security"]},"backdoor":{"id":"backdoor","title":"backdoor","definition":"A backdoor (also called a trapdoor) is a programming routine built into a system by its designer or programmer. It enables the designer or programmer to bypass system security and sneak back into the system later to access programs or files.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"backward_chaining":{"id":"backward_chaining","title":"backward chaining","definition":"In backward chaining, the expert system starts with the goal—the “then” part—and backtracks to find the right solution.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"baiting":{"id":"baiting","title":"Baiting","definition":"Baiting is similar to phishing attacks. What distinguishes it from phishing is the promise that the baiter gives to the recipient.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"big_data":{"id":"big_data","title":"Big data","definition":"Big data is data so voluminous that conventional computing methods are not able to efficiently process and manage it.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"big_idea":{"id":"big_idea","title":"Big Idea","definition":"A single complete sentence that states your point of view and what is at stake.","context":null,"tier":"exam","tags":["knaflic-ch1","band-red"],"refs":["Exam 2 Study Guide: Knaflic Ch. 1","Exam 2 Review deck, slide 41","Glossary: examples/exam2-knaflic-board"]},"biometric_security_measures":{"id":"biometric_security_measures","title":"Biometric security measures","definition":"Biometric security measures use a physiological element that is unique to a person and cannot be stolen, lost, copied, or passed on to others.","context":null,"tier":"exam","tags":["mod-05","band-green"],"refs":["Glossary: examples/mis-05-security"]},"black_hats":{"id":"black_hats","title":"Black hats","definition":"Hackers who specialize in unauthorized penetration of information systems. They attack systems for profit, fun, or political motivation or as part of a social cause. These penetration attacks often involve modifying and destroying data.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"blended_threat":{"id":"blended_threat","title":"blended threat","definition":"A blended threat is a security threat that combines the characteristics of computer viruses, worms, and other malicious codes with vulnerabilities found on public and private networks.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"brain_password":{"id":"brain_password","title":"brain password","definition":"A brain password is a digital reading of a user’s brain activity while looking at a series of images. These brain activities are recorded in a database. To log in to a system or enter a secure room, the user puts on a special hat and again watches the sequence of images. The new brain activities are compared with the ones in the database and then access is given or denied.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"business_analytics_ba":{"id":"business_analytics_ba","title":"Business analytics (BA)","definition":"Business analytics (BA) uses data and statistical methods to gain insight into the data and provide decision makers with information they can act on.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"business_continuity_planning":{"id":"business_continuity_planning","title":"business continuity planning","definition":"Business continuity planning outlines procedures for keeping an organization operational after a natural disaster or network attack.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"business_intelligence_bi":{"id":"business_intelligence_bi","title":"Business intelligence (BI)","definition":"Business intelligence (BI) provides historical, current, and predictive views of business operations and environments and gives organizations a competitive advantage in the marketplace.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"business_networking_ethics":{"id":"business_networking_ethics","title":"Business networking ethics","definition":"Business networking ethics advocates that to maintain a business network, not only should the organization provide open and fair access to all authorized users, it should also consider three types of networking: utilitarian, emotional, and virtuous.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"business_understanding":{"id":"business_understanding","title":"Business Understanding (CRISP-DM phase 1)","definition":"Understanding the project objectives and requirements from a business perspective, converting this knowledge into a BI problem definition, and developing a preliminary plan designed to achieve the objectives.","context":null,"tier":"exam","tags":["crisp-dm","band-blue"],"refs":["ITM 310 Week 7, slides 10, 12","Glossary: examples/itm310-wk07-power-bi"]},"calculated_column":{"id":"calculated_column","title":"Calculated column","definition":"A calculation added as a new column in a table, with a new value in each row. Computed at refresh time. Good for simple calculations, or when you need to slice or filter on the values.","context":null,"tier":"exam","tags":["power-bi","dax","band-yellow"],"refs":["ITM 310 Week 7, slides 24, 31","Glossary: examples/itm310-wk07-power-bi"]},"calculated_measure":{"id":"calculated_measure","title":"Calculated measure","definition":"A calculation that belongs to the entire data set, not to a table. Use it for all aggregate functions. Computed on the fly in a visual, it adapts to whatever filters are applied, and it can be used in other calculations.","context":null,"tier":"exam","tags":["power-bi","dax","band-yellow"],"refs":["Exam 2 Review deck, slide 45","itm310-wk07-power-bi glossary","Glossary: examples/exam2-knaflic-board"]},"callback_modem":{"id":"callback_modem","title":"callback modem","definition":"A callback modem verifies whether a user’s access is valid by logging the user off (after the user attempts to connect to the network) and then calling the user back at a predetermined number.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"case_based_reasoning_cbr":{"id":"case_based_reasoning_cbr","title":"case-based reasoning (CBR)","definition":"Case-based reasoning (CBR) is a problem-solving technique that matches a new case (problem) with a previously solved case and its solution, the details of which have been stored in a database. After finding a match, the CBR system offers a solution; if no match is found, even after more information is supplied, the human expert must solve the problem.","context":null,"tier":"exam","tags":["mod-09","band-blue"],"refs":["Glossary: examples/mis-09-ai"]},"cheap_fakes":{"id":"cheap_fakes","title":"Cheap fakes","definition":"Cheap fakes, sometimes known as the new fake news, are audiovisual manipulations of events created with cheap software that’s readily available on the Web and then modified using Photoshop and other tools and distributed through the Web.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"class":{"id":"class","title":"class","definition":"A class defines the format of the object and the action that it performs.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"close_and_load":{"id":"close_and_load","title":"Close & Load","definition":"The Query Editor command that finishes shaping and loads the data into the model.","context":null,"tier":"support","tags":["support","power-bi","band-blue"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"communication_method":{"id":"communication_method","title":"Communication method","definition":"How the message is delivered, such as a live presentation or a document read alone. A live talk can carry less on the slide because the speaker adds the rest; a document must stand on its own.","context":null,"tier":"exam","tags":["knaflic-ch1","band-yellow"],"refs":["Exam 2 Study Guide: Knaflic Ch. 1","Exam 2 Review deck, slide 41","Glossary: examples/exam2-knaflic-board"]},"computer_fraud":{"id":"computer_fraud","title":"Computer fraud","definition":"Computer fraud is the unauthorized use of computer data for personal gain.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"confidentiality":{"id":"confidentiality","title":"Confidentiality","definition":"Confidentiality means that a system must prevent disclosing information to anyone who is not authorized to access it.","context":null,"tier":"exam","tags":["mod-05","band-green"],"refs":["Glossary: examples/mis-05-security"]},"cookies":{"id":"cookies","title":"Cookies","definition":"Cookies are small text files with unique ID tags that are embedded in a Web browser and saved on the user’s hard drive.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"create_read_update_and_delete_crud":{"id":"create_read_update_and_delete_crud","title":"create, read, update, and delete (CRUD)","definition":"Create, read, update, and delete (CRUD) refers to a range of functions and the users who data administrators determine have permission to perform those functions.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"crisp_dm":{"id":"crisp_dm","title":"CRISP-DM","definition":"CRoss-Industry Standard Process for Data Mining: a BI and data mining project methodology. Non-proprietary, industry-neutral, and tool-neutral, with a life cycle of six phases.","context":"A standard process makes BI reliable and repeatable by people with little BI background.","tier":"exam","tags":["crisp-dm","band-red"],"refs":["ITM 310 Week 7, slides 5-8","Glossary: examples/itm310-wk07-power-bi"]},"cryptojacking":{"id":"cryptojacking","title":"Cryptojacking","definition":"Cryptojacking occurs when hackers secretly use the computing power of a user to mine cryptocurrency.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"cybersquatting":{"id":"cybersquatting","title":"cybersquatting","definition":"Cybersquatting is registering, selling, or using a domain name to profit from someone else’s trademark.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"data_dictionary":{"id":"data_dictionary","title":"data dictionary","definition":"The data dictionary stores definitions, such as data types for fields, default values, and validation rules for data in each field.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_encryption":{"id":"data_encryption","title":"Data encryption","definition":"Data encryption transforms data, called plaintext or cleartext, into a scrambled form called ciphertext that cannot be read by others.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_hierarchy":{"id":"data_hierarchy","title":"data hierarchy","definition":"A data hierarchy is the structure and organization of data, which involves fields, records, and files.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_lake":{"id":"data_lake","title":"data lake","definition":"A data lake gathers and stores data in its original format in a central location. The collected data can be structured as well as unstructured.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_mart":{"id":"data_mart","title":"data mart","definition":"A data mart is usually a smaller version of a data warehouse, used by a single department or function.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_model":{"id":"data_model","title":"data model","definition":"A data model determines how data is created, represented, organized, and maintained. It usually contains a data structure, operations, and integrity rules.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_preparation":{"id":"data_preparation","title":"Data Preparation (CRISP-DM phase 3)","definition":"Covers all activities necessary for constructing the final dataset from the initial raw data. Tasks are likely to be performed multiple times and not in any prescribed order.","context":"Can easily take 80% to 90% of a project's time.","tier":"exam","tags":["crisp-dm","band-blue"],"refs":["ITM 310 Week 7, slide 14","Glossary: examples/itm310-wk07-power-bi"]},"data_understanding":{"id":"data_understanding","title":"Data Understanding (CRISP-DM phase 2)","definition":"Starts with an initial data collection and proceeds with activities to get familiar with the data, identify data quality problems, discover first insights, and detect interesting subsets to form hypotheses for hidden information.","context":null,"tier":"exam","tags":["crisp-dm","band-blue"],"refs":["ITM 310 Week 7, slide 13","Glossary: examples/itm310-wk07-power-bi"]},"data_warehouse":{"id":"data_warehouse","title":"data warehouse","definition":"A data warehouse is a collection of data from a variety of sources used to support decision-making applications and generate business intelligence.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_driven_web_site":{"id":"data_driven_web_site","title":"data-driven Web site","definition":"A data-driven Web site acts as an interface to a database, retrieving data for users and allowing users to enter data in the database.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_mining_agents":{"id":"data_mining_agents","title":"Data-mining agents","definition":"Data-mining agents work with a data warehouse, detecting trends and discovering new information and relationships among data items that were not readily apparent.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"data_mining_analysis":{"id":"data_mining_analysis","title":"Data-mining analysis","definition":"Data-mining analysis is used to discover patterns and relationships.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"database":{"id":"database","title":"database","definition":"A database is a collection of related data that is stored in a central location or in multiple locations.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"database_administrator_dba":{"id":"database_administrator_dba","title":"database administrator (DBA)","definition":"Database administrator (DBA) in large organizations design and set up databases, establish security measures, develop recovery procedures, evaluate database performance, and add and fine-tune database functions.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"database_management_system_dbms":{"id":"database_management_system_dbms","title":"database management system (DBMS)","definition":"A database management system (DBMS) is software for creating, storing, maintaining, and accessing database files. A DBMS makes using databases more efficient.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"database_marketing":{"id":"database_marketing","title":"database marketing","definition":"Database marketing uses an organization’s database of customers and potential customers to promote products or services.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"dax":{"id":"dax","title":"DAX (Data Analysis Expressions)","definition":"A library of functions and operators used to build formulas in Power BI Desktop (and other Microsoft data systems). Starts similar to Excel functions, but goes far beyond.","context":null,"tier":"exam","tags":["power-bi","dax","band-red"],"refs":["ITM 310 Week 7, slides 20-23","Glossary: examples/itm310-wk07-power-bi"]},"dax_function":{"id":"dax_function","title":"DAX function","definition":"A function in a Power BI formula. In Total Sales = SUM(Sales[SalesAmount]), SUM is the DAX function and adds up all of the numbers in the Sales[SalesAmount] column.","context":null,"tier":"exam","tags":["power-bi","dax","band-green"],"refs":["Exam 2 Review deck, slide 45","Glossary: examples/exam2-knaflic-board"]},"deepfakes":{"id":"deepfakes","title":"Deepfakes","definition":"Deepfakes are fake videos or audio recordings that look and sound just like real events.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"delimiter":{"id":"delimiter","title":"Delimiter","definition":"A separator such as a space, comma, or semicolon between elements in imported data.","context":null,"tier":"exam","tags":["power-bi","etl","band-red"],"refs":["MindTap course glossary, Power Query module","ITM 310 Week 7, slide 30","Glossary: examples/itm310-wk07-power-bi"]},"denial_of_service_dos_attack":{"id":"denial_of_service_dos_attack","title":"denial-of-service (DoS) attack","definition":"A denial-of-service (DoS) attack floods a network or server with service requests to prevent legitimate users’ access to the system.","context":null,"tier":"exam","tags":["mod-05","band-blue"],"refs":["Glossary: examples/mis-05-security"]},"deployment_phase":{"id":"deployment_phase","title":"Deployment (CRISP-DM phase 6)","definition":"Determining how the results need to be used, who needs to use them, and how often, and implementing a repeatable BI process.","context":null,"tier":"exam","tags":["crisp-dm","band-blue"],"refs":["ITM 310 Week 7, slides 11, 17","Glossary: examples/itm310-wk07-power-bi"]},"digital_citizenship":{"id":"digital_citizenship","title":"Digital citizenship","definition":"Digital citizenship means using information technology safely, ethically, and responsibly.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"digital_divide":{"id":"digital_divide","title":"digital divide","definition":"Information technology and the Internet have created a digital divide. Computers are still not affordable for many people. The digital divide has implications for education.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"dimension_table":{"id":"dimension_table","title":"Dimension table","definition":"In a star schema, the central entity is called the Fact table. All other tables are called Dimension tables and are directly connected to the Fact table.","context":"Lookup tables such as products, stores, or dates that describe the rows in the fact table.","tier":"exam","tags":["modeling","band-green"],"refs":["ITM 310 Week 7 technical assignment, Star Schema and Visualization","Glossary: examples/itm310-wk07-power-bi"]},"disinformation":{"id":"disinformation","title":"disinformation","definition":"Disinformation is fake information that is knowingly distributed.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"distributed_database_management_system_d":{"id":"distributed_database_management_system_d","title":"distributed database management system (DDBMS)","definition":"A distributed database management system (DDBMS) stores data on multiple servers throughout an organization.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"dna_identification":{"id":"dna_identification","title":"DNA identification","definition":"DNA identification gathers a user’s unique behavioral characteristics and then creates an “eDNA” profile that is used for identification when the user tries to log in to a system.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"encapsulation":{"id":"encapsulation","title":"encapsulation","definition":"Encapsulation refers to the grouping of various objects along with their attributes and methods into a class—in other words, grouping related items into a single unit. This assists in the handling of more complex types of data, such as images and graphs.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"etl":{"id":"etl","title":"ETL (Extraction, Transformation, and Loading)","definition":"Extraction, Transformation, and Loading: selecting tables, records, and attributes, then transforming and cleaning the data.","context":null,"tier":"exam","tags":["crisp-dm","power-bi","band-green"],"refs":["ITM 310 Week 7, slide 10","Glossary: examples/itm310-wk07-power-bi"]},"evaluation_phase":{"id":"evaluation_phase","title":"Evaluation (CRISP-DM phase 5)","definition":"Evaluating whether the business objectives were achieved. For descriptive analytics, the question is whether the reporting satisfies the project objectives.","context":null,"tier":"exam","tags":["crisp-dm","band-blue"],"refs":["ITM 310 Week 7, slides 11, 16","Glossary: examples/itm310-wk07-power-bi"]},"expert_systems":{"id":"expert_systems","title":"Expert systems","definition":"Expert systems mimic human expertise in a particular field to solve a problem in a well-defined area.","context":null,"tier":"exam","tags":["mod-09","band-green"],"refs":["Glossary: examples/mis-09-ai"]},"explanation_facility":{"id":"explanation_facility","title":"explanation facility","definition":"An explanation facility performs tasks similar to what a human expert does by explaining to end users how recommendations are derived.","context":null,"tier":"exam","tags":["mod-09","band-green"],"refs":["Glossary: examples/mis-09-ai"]},"explanatory_analysis":{"id":"explanatory_analysis","title":"Explanatory analysis","definition":"Communicating one specific finding you already have to a specific audience; the pearl, not the oysters.","context":null,"tier":"exam","tags":["knaflic-ch1","band-yellow"],"refs":["Exam 2 Study Guide: Knaflic Ch. 1","Exam 2 Review deck, slide 42","Glossary: examples/exam2-knaflic-board"]},"exploratory_analysis":{"id":"exploratory_analysis","title":"Exploratory analysis","definition":"Looking through data without a fixed question, to understand it and find out what might be worth telling someone. Knaflic's picture: opening many oysters to find a few pearls.","context":null,"tier":"exam","tags":["knaflic-ch1","band-yellow"],"refs":["Exam 2 Study Guide: Knaflic Ch. 1","Exam 2 Review deck, slide 42","Glossary: examples/exam2-knaflic-board"]},"extraction_transformation_and_loading_et":{"id":"extraction_transformation_and_loading_et","title":"Extraction, transformation, and loading (ETL)","definition":"Extraction, transformation, and loading (ETL) refers to the processes used in a data warehouse. It includes extracting data from outside sources, transforming it to fit operational needs, and loading it into the end target (database or data warehouse).","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"fact_table":{"id":"fact_table","title":"Fact table","definition":"In a star schema, the central entity is called the Fact table.","context":"One row per transaction or event, holding the numbers being measured and the keys that point to the dimension tables.","tier":"exam","tags":["modeling","band-green"],"refs":["ITM 310 Week 7 technical assignment, Star Schema and Visualization","Glossary: examples/itm310-wk07-power-bi"]},"fake_news":{"id":"fake_news","title":"Fake news","definition":"Fake news is a story or hoax created to intentionally misinform or deceive readers.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"fault_tolerant_systems":{"id":"fault_tolerant_systems","title":"fault-tolerant systems","definition":"Fault-tolerant systems ensure availability in the event of a system failure by using a combination of hardware and software.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"filter_pane":{"id":"filter_pane","title":"Filters pane","definition":"Filters a visual, page, or report the way a slicer does, but is not shown on the canvas.","context":null,"tier":"support","tags":["support","power-bi","band-green"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"firewall":{"id":"firewall","title":"firewall","definition":"A firewall is a combination of hardware and software that acts as a filter or barrier between a private network and external computers or networks, including the Internet. A network administrator defines rules for access, and all other data transmissions are blocked.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"foreign_key":{"id":"foreign_key","title":"foreign key","definition":"A foreign key is a field in a relational table that matches the primary key column of another table. It can be used to cross-reference tables.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"forward_chaining":{"id":"forward_chaining","title":"forward chaining","definition":"In forward chaining, a series of “if–then–else” condition pairs is performed.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"fragmentation":{"id":"fragmentation","title":"fragmentation","definition":"The fragmentation approach to a distributed DBMS addresses how tables are divided among multiple locations. There are three variations: horizontal, vertical, and mixed.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"fuzzy_logic":{"id":"fuzzy_logic","title":"Fuzzy logic","definition":"Fuzzy logic allows a smooth, gradual transition between human and computer vocabularies and deals with variations in linguistic terms by using a degree of membership.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"general_data_protection_regulation_gdpr":{"id":"general_data_protection_regulation_gdpr","title":"General Data Protection Regulation (GDPR)","definition":"The General Data Protection Regulation (GDPR) covers a series of laws that protect European Union (EU) citizens’ personal data, including genetic data, health records, racial or ethnic origin, and religious beliefs.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"genetic_algorithms_gas":{"id":"genetic_algorithms_gas","title":"Genetic algorithms (GAs)","definition":"Genetic algorithms (GAs) are search algorithms that mimic the process of natural evolution. They are used to generate solutions to optimization and search problems using such techniques as mutation, selection, crossover, and chromosome.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"get_data":{"id":"get_data","title":"Get data","definition":"The Power BI command that connects to a data source and starts an import.","context":null,"tier":"support","tags":["power-bi","band-green"],"refs":["Exam 2 Review deck, slides 44, 46 (D)","itm310-wk07-power-bi glossary","Glossary: examples/exam2-knaflic-board"]},"global_information_system_gis":{"id":"global_information_system_gis","title":"global information system (GIS)","definition":"A global information system (GIS) works across national borders, facilitates communication between headquarters and subsidiaries in other countries, and incorporates all the technologies and applications found in a typical information system to gather, store, manipulate, and transmit data across cultural and geographic boundaries.","context":"Not the same GIS as the geographic information system in MIS 8. The course abbreviates both as GIS.","tier":"exam","tags":["mod-06","band-green"],"refs":["Glossary: examples/mis-06-global"]},"global_structure":{"id":"global_structure","title":"global structure","definition":"A global structure uses highly centralized information systems. Subsidiaries have little autonomy and rely on headquarters for all process and control decisions as well as system design and implementation.","context":null,"tier":"exam","tags":["mod-06","band-yellow"],"refs":["Glossary: examples/mis-06-global"]},"global_supply_chain_management":{"id":"global_supply_chain_management","title":"Global supply chain management","definition":"Global supply chain management incorporates management processes around the globe that integrate the network of suppliers, manufacturers, warehouses, and retail outlets in order to source high-quality raw materials, efficiently convert them to finished goods, and ship them in the right quantities to the right locations in a timely manner with the highest possible quality.","context":null,"tier":"exam","tags":["mod-06","band-red"],"refs":["Glossary: examples/mis-06-global"]},"graph_database":{"id":"graph_database","title":"graph database","definition":"A graph database is a database that uses graph structures for query operation with nodes, edges, and properties to represent and store data.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"gray_hats":{"id":"gray_hats","title":"Gray hats","definition":"As you might imagine, they are a mixture of black and white hacking. Gray hats may violate laws or ethical standards, but they do not have the malicious intent to harm a person or a system. They look for vulnerabilities in a system without the owner’s permission or knowledge. They may inform the owner that they have found vulnerabilities and will fix them for a small fee.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"green_computing":{"id":"green_computing","title":"Green computing","definition":"Green computing involves the design, manufacture, use, and disposal of computers, servers, and other computing devices so that there is minimal impact on the environment.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"hierarchical_model":{"id":"hierarchical_model","title":"hierarchical model","definition":"In a hierarchical model, the relationships between records form a treelike structure (hierarchy). Records are called nodes, and relationships between records are called branches. The node at the top is called the root, and every other node (called a child) has a parent. Nodes with the same parents are called twins or siblings.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"indexed_sequential_access_method_isam":{"id":"indexed_sequential_access_method_isam","title":"indexed sequential access method (ISAM)","definition":"With the indexed sequential access method (ISAM), records can be accessed sequentially or randomly, depending on the number being accessed. For a small number, random access is used, and for a large number, sequential access is used.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"inference_engine":{"id":"inference_engine","title":"inference engine","definition":"An inference engine is similar to the model base component of a decision support system. By using different techniques such as forward and backward chaining, it manipulates a series of rules.","context":null,"tier":"exam","tags":["mod-09","band-green"],"refs":["Glossary: examples/mis-09-ai"]},"inheritance":{"id":"inheritance","title":"inheritance","definition":"Inheritance refers to new objects being created faster and more easily by entering new data in attributes.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"integrity":{"id":"integrity","title":"Integrity","definition":"Integrity refers to the accuracy of information resources within an organization.","context":null,"tier":"exam","tags":["mod-05","band-green"],"refs":["Glossary: examples/mis-05-security"]},"intellectual_property":{"id":"intellectual_property","title":"Intellectual property","definition":"Intellectual property is a legal umbrella covering protections that involve copyrights, trademarks, trade secrets, and patents for “creations of the mind” developed by people or businesses.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"intelligent_agents":{"id":"intelligent_agents","title":"Intelligent agents","definition":"Intelligent agents are software capable of reasoning and following rule-based processes; they are becoming more popular, especially in e-commerce.","context":null,"tier":"exam","tags":["mod-09","band-red"],"refs":["Glossary: examples/mis-09-ai"]},"international_structure":{"id":"international_structure","title":"international structure","definition":"An organization with an international structure operates much like a multinational corporation, but subsidiaries depend on headquarters more for process and production decisions.","context":null,"tier":"exam","tags":["mod-06","band-yellow"],"refs":["Glossary: examples/mis-06-global"]},"intrusion_detection_system_ids":{"id":"intrusion_detection_system_ids","title":"intrusion detection system (IDS)","definition":"An intrusion detection system (IDS) can protect against both external and internal access. It is usually placed in front of a firewall and can identify attack signatures, trace patterns, generate alarms for the network administrator, and cause routers to terminate connections with suspicious sources.","context":null,"tier":"exam","tags":["mod-05","band-blue"],"refs":["Glossary: examples/mis-05-security"]},"kpi":{"id":"kpi","title":"Key performance indicator (KPI)","definition":"A measurement used by business to measure achievement of a specific goal.","context":"In Power BI, KPIs are built from calculated measures.","tier":"exam","tags":["power-bi","band-red"],"refs":["MindTap course glossary, Excel module 10","ITM 310 Week 7, slide 20","Glossary: examples/itm310-wk07-power-bi"]},"keystroke_loggers":{"id":"keystroke_loggers","title":"Keystroke loggers","definition":"Keystroke loggers are software or hardware devices that monitor and record keystrokes.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"knowledge_acquisition_facility":{"id":"knowledge_acquisition_facility","title":"knowledge acquisition facility","definition":"A knowledge acquisition facility is a software package with manual or automated methods for acquiring and incorporating new rules and facts, making the expert system capable of growth.","context":null,"tier":"exam","tags":["mod-09","band-green"],"refs":["Glossary: examples/mis-09-ai"]},"knowledge_base":{"id":"knowledge_base","title":"knowledge base","definition":"A knowledge base is similar to a database, but in addition to storing facts and figures, it keeps track of rules and explanations associated with facts.","context":null,"tier":"exam","tags":["mod-09","band-green"],"refs":["Glossary: examples/mis-09-ai"]},"knowledge_base_management_system_kbms":{"id":"knowledge_base_management_system_kbms","title":"knowledge base management system (KBMS)","definition":"A knowledge base management system (KBMS), similar to a DBMS, is used to keep the knowledge base updated with changes to facts, figures, and rules.","context":null,"tier":"exam","tags":["mod-09","band-green"],"refs":["Glossary: examples/mis-09-ai"]},"log_files":{"id":"log_files","title":"Log files","definition":"Log files, which are generated by Web server software, record a user’s actions on a Web site.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"logic_bomb":{"id":"logic_bomb","title":"logic bomb","definition":"A logic bomb is a type of Trojan program used to release a virus, worm, or other destructive code. Logic bombs are triggered at a certain time (sometimes the birthday of a famous person) or by a specific event, such as a user pressing the Enter key or running a certain program.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"logical_view":{"id":"logical_view","title":"logical view","definition":"The logical view involves how information appears to users and how it can be organized and retrieved.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"machine_learning":{"id":"machine_learning","title":"Machine learning","definition":"Machine learning is a process and procedure by which knowledge is gained through experience. In other words, computers learn without being explicitly programmed.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"macro_viruses":{"id":"macro_viruses","title":"Macro viruses","definition":"A type of virus that uses a program’s own macro programming language to distribute the virus.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"misinformation":{"id":"misinformation","title":"Misinformation","definition":"Misinformation is fake information that is distributed to an audience, regardless of intent to mislead.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"modeling_phase":{"id":"modeling_phase","title":"Modeling (CRISP-DM phase 4)","definition":"Various modeling techniques are selected and applied: select the techniques, build the models, and assess them. It may be necessary to step back to the data preparation phase.","context":null,"tier":"exam","tags":["crisp-dm","band-blue"],"refs":["ITM 310 Week 7, slides 11, 15","Glossary: examples/itm310-wk07-power-bi"]},"monitoring_and_surveillance_agents":{"id":"monitoring_and_surveillance_agents","title":"Monitoring and surveillance agents","definition":"Monitoring and surveillance agents usually track and report on computer equipment and network systems to predict when a system crash or failure might occur.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"multinational_corporations_mncs":{"id":"multinational_corporations_mncs","title":"multinational corporations (MNCs)","definition":"A multinational corporation (MNC) is an organization with assets and operations in at least one country other than its home country. An MNC delivers products and services across national borders and is usually centrally managed from its headquarters.","context":null,"tier":"exam","tags":["mod-06","band-red"],"refs":["Glossary: examples/mis-06-global"]},"multinational_structure":{"id":"multinational_structure","title":"multinational structure","definition":"In a multinational structure, production, sales, and marketing are decentralized, and financial management remains the parent’s responsibility.","context":null,"tier":"exam","tags":["mod-06","band-yellow"],"refs":["Glossary: examples/mis-06-global"]},"natural_language_processing_nlp":{"id":"natural_language_processing_nlp","title":"natural-language processing (NLP)","definition":"Natural-language processing (NLP) was developed so users could communicate with computers in human language.","context":null,"tier":"exam","tags":["mod-09","band-red"],"refs":["Glossary: examples/mis-09-ai"]},"network_model":{"id":"network_model","title":"network model","definition":"The network model is similar to the hierarchical model, but records are organized differently. Unlike the hierarchical model, each record in the network model can have multiple parent and child records.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"nonrepudiation":{"id":"nonrepudiation","title":"nonrepudiation","definition":"Nonrepudiation is a method for binding all parties to a contract.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"normalization":{"id":"normalization","title":"normalization","definition":"Normalization improves database efficiency by eliminating redundant data and ensuring that only related data is stored in a table.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"object":{"id":"object","title":"object","definition":"An object is an item that contains both data and the procedures that read and manipulate it.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"object_oriented_databases":{"id":"object_oriented_databases","title":"object-oriented databases","definition":"In object-oriented databases, both data and their relationships are contained in a single object. An object consists of attributes and methods that can be performed on the object’s data.","context":null,"tier":"exam","tags":["mod-03","band-green"],"refs":["Glossary: examples/mis-03-data-bi"]},"offshore_outsourcing":{"id":"offshore_outsourcing","title":"Offshore outsourcing","definition":"With offshore outsourcing, an organization chooses an outsourcing firm in another country that can provide needed services and products.","context":null,"tier":"exam","tags":["mod-06","band-red"],"refs":["Glossary: examples/mis-06-global"]},"online_analytical_processing_olap":{"id":"online_analytical_processing_olap","title":"Online analytical processing (OLAP)","definition":"Online analytical processing (OLAP) generates business intelligence. It uses multiple sources of information and provides multidimensional analysis, such as viewing data based on time, product, and location.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"online_transaction_processing_oltp":{"id":"online_transaction_processing_oltp","title":"online transaction processing (OLTP)","definition":"Online transaction processing (OLTP) is used to facilitate and manage transaction-oriented applications, such as point-of-sale, data entry, and retrieval transaction processing. It generally uses internal data and responds in real time.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"password":{"id":"password","title":"password","definition":"A password is a combination of numbers, characters, and symbols that a user enters to gain access to a system.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"personal_agents":{"id":"personal_agents","title":"Personal agents","definition":"Personal agents perform specific tasks for a user, such as remembering information for filling out Web forms or completing e-mail addresses after the first few characters are typed.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"pharming":{"id":"pharming","title":"Pharming","definition":"Similar to phishing, pharming directs Internet users to fraudulent Web sites with the intention of stealing their personal information, such as Social Security numbers, passwords, bank account numbers, and credit card numbers. The difference is that pharmers usually hijack an official Web site, then alter its IP address so that users who enter the correct Web address are directed to the pharmer’s fraudulent Web site.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"phishing":{"id":"phishing","title":"Phishing","definition":"Phishing is the transmission of fraudulent e-mails that seem to come from legitimate sources, such as a bank or university.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"physical_security_measures":{"id":"physical_security_measures","title":"Physical security measures","definition":"Physical security measures primarily control access to computers and networks, and they include devices for securing computers and peripherals from theft.","context":null,"tier":"exam","tags":["mod-05","band-green"],"refs":["Glossary: examples/mis-05-security"]},"physical_view":{"id":"physical_view","title":"physical view","definition":"The physical view involves how data is stored on and retrieved from storage media, such as hard disks or magnetic tapes.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"pki_public_key_infrastructure":{"id":"pki_public_key_infrastructure","title":"PKI (public key infrastructure)","definition":"A PKI (public key infrastructure) enables users of a public network such as the Internet to securely and privately exchange data through the use of a pair of keys—a public one and a private one—that is obtained from a trusted authority and shared through that authority.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"power_bi":{"id":"power_bi","title":"Power BI","definition":"Power BI is a platform that allows a user to analyze and visualize data from different sources with different formats.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"power_bi_desktop":{"id":"power_bi_desktop","title":"Power BI Desktop","definition":"Power BI on a single machine. On-premise.","context":null,"tier":"exam","tags":["power-bi","deployment","band-yellow"],"refs":["ITM 310 Week 7, slide 17","Glossary: examples/itm310-wk07-power-bi"]},"power_bi_mobile":{"id":"power_bi_mobile","title":"Power BI Mobile","definition":"Power BI on smartphones and tablets, one of the deployment options.","context":null,"tier":"exam","tags":["power-bi","deployment","band-yellow"],"refs":["ITM 310 Week 7, slide 17 and notes to slide 16","Glossary: examples/itm310-wk07-power-bi"]},"power_bi_reports":{"id":"power_bi_reports","title":"Power BI reports","definition":"Power BI's data visualization tools: interactive visual reports that let decision makers quickly and visually explore their data.","context":null,"tier":"exam","tags":["power-bi","band-red"],"refs":["ITM 310 Week 7, slide 16","Glossary: examples/itm310-wk07-power-bi"]},"power_bi_service":{"id":"power_bi_service","title":"Power BI service","definition":"Power BI via Office 365. Cloud based, so strictly off-premise.","context":null,"tier":"exam","tags":["power-bi","deployment","band-yellow"],"refs":["ITM 310 Week 7, slide 17","Glossary: examples/itm310-wk07-power-bi"]},"query_editor":{"id":"query_editor","title":"Power Query Editor (Query Editor)","definition":"Power BI's ETL tool, used for shaping and mashing up data. It can import and merge data from a variety of sources, append tables together, and set table and column properties such as data types.","context":"Microsoft's current name is Power Query Editor, opened with Transform data on the Home tab. The Week 7 slides call it the Query Editor.","tier":"exam","tags":["power-bi","band-green"],"refs":["ITM 310 Week 7, slides 13-14, 30","Glossary: examples/itm310-wk07-power-bi"]},"presentation_context":{"id":"presentation_context","title":"Presentation context","definition":"What you must settle before building anything: who the audience is, what you need them to know or do, and how the data can help you make the point.","context":null,"tier":"exam","tags":["knaflic-ch1","band-green"],"refs":["Exam 2 Study Guide: Knaflic Ch. 1","Exam 2 Review deck, slide 41","Glossary: examples/exam2-knaflic-board"]},"primary_key":{"id":"primary_key","title":"primary key","definition":"A primary key uniquely identifies every record in a relational database. Examples include student ID numbers, account numbers, Social Security numbers, and invoice numbers.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"query_by_example_qbe":{"id":"query_by_example_qbe","title":"query by example (QBE)","definition":"With query by example (QBE), you request data from a database by constructing a statement made up of query forms. With current graphical databases, you simply click to select query forms instead of having to remember keywords, as you do with SQL. You can add AND, OR, and NOT operators to the QBE form to fine-tune the query.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"quid_pro_quo":{"id":"quid_pro_quo","title":"quid pro quo","definition":"Similar to baiting, quid pro quo involves a hacker requesting the exchange of critical data or login information for a service or prize.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"random_access_file_structure":{"id":"random_access_file_structure","title":"random access file structure","definition":"In a random access file structure, records can be accessed in any order, regardless of their physical locations in storage media. This method of access is fast and very effective when a small number of records needs to be processed daily or weekly.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"relational_model":{"id":"relational_model","title":"relational model","definition":"A relational model uses a two-dimensional table of rows and columns of data. Rows are records (also called tuples), and columns are fields (also referred to as attributes).","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"relationship":{"id":"relationship","title":"Relationship (Power BI model)","definition":"A link between tables in the data model, created on Primary Key and Foreign Key fields that match (have the same ranges of values).","context":null,"tier":"exam","tags":["power-bi","modeling","band-green"],"refs":["ITM 310 Week 7, slide 20","Glossary: examples/itm310-wk07-power-bi"]},"replication":{"id":"replication","title":"replication","definition":"The replication approach to a distributed DBMS has each site store a copy of the data in the organization’s database.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"report_canvas":{"id":"report_canvas","title":"Report canvas","definition":"The page in Power BI Desktop where visuals are built by dragging fields onto it.","context":null,"tier":"support","tags":["support","power-bi","band-green"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"robots":{"id":"robots","title":"Robots","definition":"Robots are one of the most successful applications of AI. They perform well at simple, repetitive tasks and can be used to free workers from tedious or hazardous jobs.","context":null,"tier":"exam","tags":["mod-09","band-red"],"refs":["Glossary: examples/mis-09-ai"]},"rootkit":{"id":"rootkit","title":"rootkit","definition":"A rootkit is a series of software tools that enable an unauthorized user to gain access to a computer or network system without being detected.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"script_kiddies":{"id":"script_kiddies","title":"Script kiddies","definition":"Inexperienced, usually young hackers who use programs that others have developed to attack computer and network systems and deface Web sites.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"secure_sockets_layer_ssl":{"id":"secure_sockets_layer_ssl","title":"Secure Sockets Layer (SSL)","definition":"Secure Sockets Layer (SSL) is a commonly used encryption protocol that manages transmission security on the Internet.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"sequential_access_file_structure":{"id":"sequential_access_file_structure","title":"sequential access file structure","definition":"In a sequential access file structure, records in files are organized and processed in numerical or sequential order, typically the order in which they were entered.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"shopping_and_information_agents":{"id":"shopping_and_information_agents","title":"Shopping and information agents","definition":"Shopping and information agents help users navigate through the vast resources available on the Web and provide better results in finding information. These agents can navigate the Web much faster than humans and gather more consistent, detailed information. They can serve as search engines, site reminders, or personal surfing assistants.","context":null,"tier":"exam","tags":["mod-09","band-yellow"],"refs":["Glossary: examples/mis-09-ai"]},"slicer":{"id":"slicer","title":"Slicer","definition":"A visual on the report canvas that filters the other visuals on the page when you pick a value.","context":null,"tier":"support","tags":["support","power-bi","band-yellow"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"sniffing":{"id":"sniffing","title":"Sniffing","definition":"Sniffing is capturing and recording network traffic.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"social_engineering":{"id":"social_engineering","title":"social engineering","definition":"Social engineering takes advantage of the human element of a security system to trick others into revealing private information.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"social_media_networking_ethics":{"id":"social_media_networking_ethics","title":"Social media networking ethics","definition":"Social media networking ethics advocates that social media should be open and provide fair access to all of its users.","context":null,"tier":"exam","tags":["mod-04","band-yellow"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"soft_robot":{"id":"soft_robot","title":"soft robot","definition":"A soft robot is made of elastomer, is simpler to make and less expensive than conventional robots, and is used for an increasing number of applications.","context":null,"tier":"exam","tags":["mod-09","band-red"],"refs":["Glossary: examples/mis-09-ai"]},"spam":{"id":"spam","title":"spam","definition":"Spam is an unsolicited e-mail sent for advertising purposes.","context":null,"tier":"exam","tags":["mod-04","band-red"],"refs":["Glossary: examples/mis-04-ethics-legal"]},"spoofing":{"id":"spoofing","title":"Spoofing","definition":"Spoofing is an attempt to gain access to a network by posing as an authorized user in order to find sensitive information, such as passwords and credit card information.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"spyware":{"id":"spyware","title":"Spyware","definition":"Spyware is software that secretly gathers information about users while they browse the Web.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"star_schema":{"id":"star_schema","title":"Star schema","definition":"A star schema is a type of relational data structure optimized for analytics.","context":"A way of arranging a data model with one central table of transactions surrounded by lookup tables, each joined to it by a key.","tier":"exam","tags":["modeling","band-green"],"refs":["ITM 310 Week 7 technical assignment, Star Schema and Visualization","Glossary: examples/itm310-wk07-power-bi"]},"storyboarding":{"id":"storyboarding","title":"Storyboarding","definition":"Sketching the outline of a presentation, one note per slide, and rearranging it before building anything.","context":null,"tier":"exam","tags":["knaflic-ch1","band-red"],"refs":["Exam 2 Study Guide: Knaflic Ch. 1","Exam 2 Review deck, slide 41","Glossary: examples/exam2-knaflic-board"]},"structured_query_language_sql":{"id":"structured_query_language_sql","title":"Structured Query Language (SQL)","definition":"Structured Query Language (SQL) is a standard fourth-generation query language used by many DBMS packages, such as Oracle Database 12 and Microsoft SQL Server. SQL consists of several keywords that specify actions to take.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"symmetric_encryption":{"id":"symmetric_encryption","title":"symmetric encryption","definition":"In symmetric encryption (also called secret key encryption), the same key is used to encrypt and decrypt the message. The sender and receiver must agree on the key and keep it secret.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"data_view":{"id":"data_view","title":"Table view","definition":"The Power BI Desktop view that shows the rows of each table. The course recommends creating calculations here, from the Modeling tab.","context":"Microsoft's current name is Table view, one of the three view icons on the left side of Power BI Desktop. The Week 7 slides call it the Data view.","tier":"support","tags":["support","power-bi","band-green"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"tableau":{"id":"tableau","title":"Tableau","definition":"Tableau is a data visualization tool used for generating business intelligence. It is used to analyze data for generating trends using graphs and charts.","context":null,"tier":"exam","tags":["mod-03","band-red"],"refs":["Glossary: examples/mis-03-data-bi"]},"text_mining_analysis":{"id":"text_mining_analysis","title":"Text-mining analysis","definition":"Text-mining analysis, or text data-mining analysis is the process of analyzing vast amounts of textual information to capture key concepts, trends, and hidden relationships.","context":null,"tier":"exam","tags":["mod-03","band-yellow"],"refs":["Glossary: examples/mis-03-data-bi"]},"transborder_data_flow_tdf":{"id":"transborder_data_flow_tdf","title":"transborder data flow (TDF)","definition":"Transborder data flow (TDF) restricts what type of data can be captured and transmitted in foreign countries.","context":null,"tier":"exam","tags":["mod-06","band-red"],"refs":["Glossary: examples/mis-06-global"]},"transnational_structure":{"id":"transnational_structure","title":"transnational structure","definition":"In an organization with a transnational structure, the parent and all the subsidiaries work together in designing policies, procedures, and logistics for delivering products and services to the right market.","context":null,"tier":"exam","tags":["mod-06","band-yellow"],"refs":["Glossary: examples/mis-06-global"]},"transport_layer_security_tls":{"id":"transport_layer_security_tls","title":"Transport Layer Security (TLS)","definition":"Transport Layer Security (TLS) is a cryptographic protocol that ensures data security and integrity over public networks, such as the Internet.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"trojan_programs":{"id":"trojan_programs","title":"Trojan programs","definition":"A Trojan program contains code intended to disrupt a computer, network, or Web site, and it is usually hidden inside a popular program. Users run the program, unaware that the malicious program is also running in the background.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"virtual_private_network_vpn":{"id":"virtual_private_network_vpn","title":"virtual private network (VPN)","definition":"A virtual private network (VPN) provides a secure “tunnel” through the Internet for transmitting messages and data via a private network.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"virus":{"id":"virus","title":"virus","definition":"A virus consists of self-propagating program code that is triggered by a specified time or event. When the infected program or operating system is used, the virus attaches itself to other files, and the cycle continues.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"visual_details":{"id":"visual_details","title":"Visual details area","definition":"The course's name for the area under Visualizations where fields go into the axes, legend, values, and details of the selected visual.","context":null,"tier":"support","tags":["support","power-bi","band-green"],"refs":["Glossary: examples/itm310-wk07-power-bi"]},"white_hats":{"id":"white_hats","title":"White hats","definition":"Also known as ethical hackers, these are computer security experts who specialize in penetration testing and other testing methods to ensure that a company’s information systems are secure.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"worm":{"id":"worm","title":"worm","definition":"A worm travels from computer to computer in a network, but it does not usually erase data. Unlike viruses, worms are independent programs that can spread themselves without having to be attached to a host program.","context":null,"tier":"exam","tags":["mod-05","band-yellow"],"refs":["Glossary: examples/mis-05-security"]},"zero_login":{"id":"zero_login","title":"Zero login","definition":"Zero login assumes that devices will be smart and secure enough to quickly recognize users by their unique features, such as their voice and their typing patterns.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]},"zero_trust_security":{"id":"zero_trust_security","title":"Zero trust security","definition":"Zero trust security requires every person and every device that accesses a network to be secure, regardless of whether the access is within the organization or outside of it.","context":null,"tier":"exam","tags":["mod-05","band-red"],"refs":["Glossary: examples/mis-05-security"]}};
